import osfrom datetime import datetime, timedeltafrom fastapi import Depends, HTTPException, statusfrom fastapi.security import OAuth2PasswordBearerfrom jose import JWTError, jwtfrom passlib.context import CryptContextfrom sqlalchemy.orm import Sessionfrom .database import get_db, SessionLocalfrom .models import UserSECRET_KEY = os.environ.get("SECRET_KEY", "dev-secret")ALGORITHM = "HS256"EXPIRE_MIN = int(os.environ.get("TOKEN_EXPIRE_MINUTES", 120))pwd = CryptContext(schemes=["bcrypt"], deprecated="auto")oauth2 = OAuth2PasswordBearer(tokenUrl="/api/login")def create_token(username: str) -> str:    payload = {"sub": username, "exp": datetime.utcnow() + timedelta(minutes=EXPIRE_MIN)}    return jwt.encode(payload, SECRET_KEY, algorithm=ALGORITHM)def verify_user(db: Session, username: str, password: str) -> bool:    user = db.query(User).filter(User.username == username).first()    return bool(user and pwd.verify(password, user.password_hash))def get_current_user(token: str = Depends(oauth2), db: Session = Depends(get_db)) -> User:    exc = HTTPException(status.HTTP_401_UNAUTHORIZED, "Nieprawidłowy token")    try:        payload = jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM])        username = payload.get("sub")    except JWTError:        raise exc    user = db.query(User).filter(User.username == username).first()    if not user:        raise exc    return userdef require_roles(*roles):    """Fabryka zależności FastAPI - wymaga, by zalogowany użytkownik    miał jedną z podanych ról."""    def checker(user: User = Depends(get_current_user)) -> User:        if user.role not in roles:            raise HTTPException(status.HTTP_403_FORBIDDEN, "Brak uprawnień do tej operacji")        return user    return checkerrequire_admin = require_roles("admin")require_manager = require_roles("admin", "manager")def hash_password(password: str) -> str:    return pwd.hash(password)def seed_admin():    db = SessionLocal()    try:        username = os.environ.get("ADMIN_USER", "admin")        password = os.environ.get("ADMIN_PASSWORD", "admin123")        existing = db.query(User).filter(User.username == username).first()        if not existing:            db.add(User(username=username, password_hash=pwd.hash(password),                        role="admin", is_protected=True))            db.commit()        else:            changed = False            if existing.role != "admin":                existing.role = "admin"                changed = True            if not existing.is_protected:                existing.is_protected = True                changed = True            if changed:                db.commit()    finally:        db.close()